CREATE TABLE "users" (
  "user_id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "username" varchar(30) UNIQUE NOT NULL,
  "email" varchar(255) UNIQUE NOT NULL,
  "password_hash" varchar(255) NOT NULL,
  "created_at" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "status" varchar(12) NOT NULL DEFAULT 'active',
  CONSTRAINT "chk_users_status"
    CHECK ("status" IN ('active', 'suspended', 'deleted'))
);

CREATE TABLE "profiles" (
  "user_id" int PRIMARY KEY,
  "display_name" varchar(60) NOT NULL,
  "bio" varchar(500)
);

CREATE TABLE "project_categories" (
  "category_id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "category_name" varchar(80) UNIQUE NOT NULL,
  "description" varchar(500)
);

CREATE TABLE "projects" (
  "project_id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "owner_id" int NOT NULL,
  "category_id" int,
  "project_name" varchar(120) NOT NULL,
  "description" varchar(2000) NOT NULL,
  "goal_hours" numeric(7,2) NOT NULL,
  "status" varchar(15) NOT NULL DEFAULT 'open',
  "created_at" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "updated_at" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT "chk_projects_goal_hours"
    CHECK ("goal_hours" > 0),
  CONSTRAINT "chk_projects_status"
    CHECK ("status" IN ('open', 'in_progress', 'completed', 'cancelled'))
);

CREATE TABLE "project_files" (
  "file_id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "project_id" int NOT NULL,
  "uploaded_by" int NOT NULL,
  "original_file_name" varchar(255) NOT NULL,
  "storage_name" varchar(500) UNIQUE NOT NULL,
  "content_type" varchar(100),
  "file_size_bytes" bigint,
  "uploaded_at" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT "chk_project_files_size"
    CHECK ("file_size_bytes" IS NULL OR "file_size_bytes" >= 0)
);

CREATE TABLE "project_contributions" (
  "contribution_id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "project_id" int NOT NULL,
  "user_id" int NOT NULL,
  "hours_committed" decimal(7,2) NOT NULL,
  "hours_completed" decimal(7,2) NOT NULL DEFAULT 0,
  "status" varchar(15) NOT NULL DEFAULT 'active',
  "committed_at" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "updated_at" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT "chk_contributions_hours_committed"
    CHECK ("hours_committed" >= 0),
  CONSTRAINT "chk_contributions_hours_completed"
    CHECK ("hours_completed" >= 0),
  CONSTRAINT "chk_contributions_hours_limit"
    CHECK ("hours_completed" <= "hours_committed"),
  CONSTRAINT "chk_contributions_status"
    CHECK ("status" IN ('active', 'withdrawn', 'completed'))
);

CREATE TABLE "contribution_history" (
  "history_id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "contribution_id" int NOT NULL,
  "changed_by" int NOT NULL,
  "hours_type" varchar(12) NOT NULL,
  "previous_hours" decimal(7,2) NOT NULL,
  "new_hours" decimal(7,2) NOT NULL,
  "changed_at" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "notes" varchar(500),
  CONSTRAINT "chk_contribution_history_hours_type"
    CHECK ("hours_type" IN ('committed', 'completed')),
  CONSTRAINT "chk_contribution_history_previous"
    CHECK ("previous_hours" >= 0),
  CONSTRAINT "chk_contribution_history_new"
    CHECK ("new_hours" >= 0)
);

CREATE TABLE "project_upvotes" (
  "user_id" int NOT NULL,
  "project_id" int NOT NULL,
  "created_at" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY ("user_id", "project_id")
);

CREATE TABLE "project_comments" (
  "comment_id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "project_id" int NOT NULL,
  "commenter_id" int NOT NULL,
  "parent_comment_id" int,
  "comment_text" varchar(2000) NOT NULL,
  "created_at" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "updated_at" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP
);

CREATE INDEX "idx_projects_owner"
  ON "projects" ("owner_id");

CREATE INDEX "idx_projects_category"
  ON "projects" ("category_id");

CREATE INDEX "idx_projects_name"
  ON "projects" ("project_name");

CREATE INDEX "idx_projects_status"
  ON "projects" ("status");

CREATE INDEX "idx_project_files_project"
  ON "project_files" ("project_id");

CREATE INDEX "idx_project_files_uploader"
  ON "project_files" ("uploaded_by");

CREATE UNIQUE INDEX "uq_contributions_project_user"
  ON "project_contributions" ("project_id", "user_id");

CREATE INDEX "idx_contribution_history_contribution"
  ON "contribution_history" ("contribution_id");

CREATE INDEX "idx_contribution_history_changed_by"
  ON "contribution_history" ("changed_by");

CREATE INDEX "idx_project_upvotes_project"
  ON "project_upvotes" ("project_id");

CREATE INDEX "idx_project_comments_project_created"
  ON "project_comments" ("project_id", "created_at");

CREATE INDEX "idx_project_comments_parent"
  ON "project_comments" ("project_id", "parent_comment_id");

CREATE UNIQUE INDEX "uq_project_comments_project_comment"
  ON "project_comments" ("project_id", "comment_id");

COMMENT ON COLUMN "users"."status"
  IS 'active, suspended, deleted';

COMMENT ON COLUMN "projects"."status"
  IS 'open, in_progress, completed, cancelled';

COMMENT ON COLUMN "project_contributions"."status"
  IS 'active, withdrawn, completed';

COMMENT ON COLUMN "contribution_history"."hours_type"
  IS 'committed, completed';

ALTER TABLE "profiles"
  ADD CONSTRAINT "fk_profiles_user"
  FOREIGN KEY ("user_id")
  REFERENCES "users" ("user_id")
  ON DELETE CASCADE
  DEFERR
